// ---------- Logging ----------
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
enum Level { Error=0, Warn=1, Info=2, Debug=3, Trace=4 }

impl Level {
    fn from_str(s: &str) -> Option<Option<Level>> {
        match s.to_ascii_lowercase().as_str() {
            "off" => Some(None),
            "error" => Some(Some(Level::Error)),
            "warn" | "warning" => Some(Some(Level::Warn)),
            "info" => Some(Some(Level::Info)),
            "debug" => Some(Some(Level::Debug)),
            "trace" => Some(Some(Level::Trace)),
            _ => None,
        }
    }
    fn as_str(&self) -> &'static str {
        match self { Level::Error=>"ERROR", Level::Warn=>"WARN", Level::Info=>"INFO", Level::Debug=>"DEBUG", Level::Trace=>"TRACE" }
    }
    fn color(&self) -> &'static str {
        match self { Level::Error=>"31", Level::Warn=>"33", Level::Info=>"32", Level::Debug=>"34", Level::Trace=>"35" }
    }
}

struct Filter {
    global: Option<Level>,
    targets: Vec<(String, Option<Level>)>,
}

static FILTER: OnceLock<Filter> = OnceLock::new();

fn get_filter() -> &'static Filter {
    FILTER.get_or_init(|| {
        match std::env::var("RUST_LOG") {
            Err(_) => Filter { global: Some(Level::Warn), targets: vec![] },
            Ok(s) => {
                let trimmed = s.trim();
                if trimmed.is_empty() {
                    return Filter { global: None, targets: vec![] };
                }
                let mut global: Option<Option<Level>> = None;
                let mut targets: Vec<(String, Option<Level>)> = vec![];
                for part in trimmed.split(',') {
                    let part = part.trim();
                    if part.is_empty() { continue; }
                    if let Some((t, l)) = part.split_once('=') {
                        let t = t.trim().to_string();
                        let l = l.trim();
                        if let Some(lvl) = Level::from_str(l) {
                            targets.push((t, lvl));
                        }
                    } else {
                        if let Some(lvl) = Level::from_str(part) {
                            global = Some(lvl);
                        }
                    }
                }
                let g = match global {
                    Some(v) => v,
                    None => {
                        if targets.is_empty() { Some(Level::Warn) } else { None }
                    }
                };
                Filter { global: g, targets }
            }
        }
    })
}

fn should_log(level: Level, target: &str) -> bool {
    let f = get_filter();
    // find longest matching target
    let mut best: Option<&(String, Option<Level>)> = None;
    let mut best_len = 0;
    for t in &f.targets {
        let dt = &t.0;
        if target == dt || target.starts_with(&format!("{}::", dt)) {
            if dt.len() > best_len {
                best_len = dt.len();
                best = Some(t);
            }
        }
    }
    if let Some((_, lvl_opt)) = best {
        match lvl_opt {
            None => return false,
            Some(max) => return level <= *max,
        }
    }
    match f.global {
        None => false,
        Some(max) => level <= max,
    }
}

static LOG_MUTEX: OnceLock<Mutex<()>> = OnceLock::new();
fn log_msg(level: Level, target: &str, msg: String) {
    if !should_log(level, target) { return; }
    let _guard = LOG_MUTEX.get_or_init(|| Mutex::new(())).lock().unwrap();
    let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.6fZ").to_string();
    let no_color = std::env::var("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false);
    if no_color {
        println!("{} {:>5} {}: {}", ts, level.as_str(), target, msg);
    } else {
        println!("\x1b[2m{}\x1b[0m \x1b[{}m{:>5}\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", ts, level.color(), level.as_str(), target, msg);
    }
}
fn log_error(t: &str, m: String) { log_msg(Level::Error, t, m); }
fn log_warn(t: &str, m: String) { log_msg(Level::Warn, t, m); }
fn log_info(t: &str, m: String) { log_msg(Level::Info, t, m); }
fn log_debug(t: &str, m: String) { log_msg(Level::Debug, t, m); }

// ---------- Size parsing ----------
fn parse_size(s: &str) -> Result<u64, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    let last = s.chars().last().unwrap();
    let (num_part, mult) = match last {
        'k' => (&s[..s.len()-1], 1024u64),
        'M' => (&s[..s.len()-1], 1024*1024u64),
        'G' => (&s[..s.len()-1], 1024*1024*1024u64),
        'T' => (&s[..s.len()-1], 1024*1024*1024*1024u64),
        _ => (s, 1u64),
    };
    if num_part.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    match num_part.parse::<u64>() {
        Ok(n) => Ok(n.wrapping_mul(mult)),
        Err(e) => Err(e.to_string()),
    }
}

