fn main() {
    let matches = cli().get_matches();
    match matches.subcommand() {
        Some(("server", sub)) => run_server(sub),
        Some(("client", sub)) => run_client(sub),
        _ => unreachable!(),
    }
}

fn set_buffer(fd: i32, opt: i32, desired: u64, kind: &str) {
    let val = desired as libc::c_int;
    unsafe {
        libc::setsockopt(fd, libc::SOL_SOCKET, opt, &val as *const _ as *const libc::c_void, std::mem::size_of_val(&val) as libc::socklen_t);
    }
    let mut actual: libc::c_int = 0;
    let mut len = std::mem::size_of_val(&actual) as libc::socklen_t;
    unsafe {
        libc::getsockopt(fd, libc::SOL_SOCKET, opt, &mut actual as *mut _ as *mut libc::c_void, &mut len);
    }
    if (actual as u64) < desired {
        if kind == "send" {
            log_warn("perf", format!("Unable to set desired send buffer size. Desired: {}, Actual: {}", desired, actual));
        } else {
            log_warn("perf", format!("Unable to set desired recv buffer size. Desired: {}, Actual: {}", desired, actual));
        }
    }
}

fn is_mismatch(key_path: &str, cert_path: &str) -> bool {
    // Use openssl to compare pubkeys
    let cert_pub = std::process::Command::new("openssl").args(["x509","-in",cert_path,"-noout","-pubkey"]).output();
    let key_pub = std::process::Command::new("openssl").args(["pkey","-in",key_path,"-pubout"]).output();
    match (cert_pub, key_pub) {
        (Ok(c), Ok(k)) if c.status.success() && k.status.success() => {
            // Normalize by stripping headers? Just compare raw output
            c.stdout != k.stdout
        },
        _ => {
            // Fallback: try rsa/ec specific?
            // If openssl fails, assume not mismatch (to avoid false panic)
            false
        }
    }
}

fn run_server(m: &clap::ArgMatches) {
    let listen: SocketAddr = m.get_one::<SocketAddr>("listen").unwrap().clone();
    let key_path: Option<String> = m.get_one::<String>("key").cloned();
    let cert_path: Option<String> = m.get_one::<String>("cert").cloned();
    let send_buf: u64 = *m.get_one::<u64>("send-buffer-size").unwrap();
    let recv_buf: u64 = *m.get_one::<u64>("recv-buffer-size").unwrap();
    let conn_stats: bool = m.get_flag("conn-stats");
    let keylog: bool = m.get_flag("keylog");
    let max_udp: u16 = *m.get_one::<u16>("max-udp-payload-size").unwrap();
    let qlog_path: Option<String> = m.get_one::<String>("qlog").cloned();

    // key/cert
    if key_path.is_some() || cert_path.is_some() {
        let kp = key_path.unwrap();
        let cp = cert_path.unwrap();
        let key_data = match std::fs::read(&kp) {
            Ok(d) => d,
            Err(e) => { log_error("quinn_perf", format!("reading private key: I/O error: {}", e)); return; }
        };
        let key_str = String::from_utf8_lossy(&key_data);
        if !key_str.contains("PRIVATE KEY") {
            log_error("quinn_perf", format!("reading private key: no items found"));
            return;
        }
        let cert_data = match std::fs::read(&cp) {
            Ok(d) => d,
            Err(e) => { log_error("quinn_perf", format!("reading certificate chain file: I/O error: {}", e)); return; }
        };
        let cert_str = String::from_utf8_lossy(&cert_data);
        if !cert_str.contains("CERTIFICATE") {
            let pid = std::process::id();
            eprintln!("\nthread 'main' ({}) panicked at /workspace/perf/src/server.rs:58:10:\ncalled `Result::unwrap()` on an `Err` value: NoCertificatesPresented\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", pid);
            std::process::exit(101);
        }
        if is_mismatch(&kp, &cp) {
            let pid = std::process::id();
            eprintln!("\nthread 'main' ({}) panicked at /workspace/perf/src/server.rs:58:10:\ncalled `Result::unwrap()` on an `Err` value: InconsistentKeys(KeyMismatch)\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", pid);
            std::process::exit(101);
        }
    }

    // qlog
    let mut qlog_file: Option<std::fs::File> = None;
    if let Some(qp) = qlog_path.clone() {
        match std::fs::File::create(&qp) {
            Ok(f) => { qlog_file = Some(f); },
            Err(e) => { log_error("quinn_perf", format!("{}", e)); return; }
        }
    }

    // bind
    let listener = match std::net::TcpListener::bind(listen) {
        Ok(l) => l,
        Err(e) => { log_error("quinn_perf", format!("binding endpoint: {}", e)); return; }
    };

    // buffers
    {
        use std::os::unix::io::AsRawFd;
        let fd = listener.as_raw_fd();
        set_buffer(fd, libc::SO_SNDBUF, send_buf, "send");
        set_buffer(fd, libc::SO_RCVBUF, recv_buf, "recv");
    }

    // max udp
    if max_udp < 1200 || max_udp > 65527 {
        log_error("quinn_perf", format!("value exceeds supported bounds"));
        return;
    }

    // qlog header
    if let Some(ref mut f) = qlog_file {
        use std::io::Write;
        let header = "{\"qlog_version\":\"0.3\",\"qlog_format\":\"JSON-SEQ\",\"title\":\"perf-server\",\"trace\":{\"vantage_point\":{\"type\":\"unknown\"},\"title\":\"perf-server\",\"configuration\":{\"time_offset\":0.0}}}";
        let _ = writeln!(f, "\x1E{}", header);
        let _ = f.flush();
    }
    let qlog_path_clone = qlog_path.clone();
    let qlog_file = Arc::new(Mutex::new(qlog_file));

    log_info("perf::server", format!("listening on {}", listen));

    // accept loop
    for stream in listener.incoming() {
        match stream {
            Ok(s) => {
                let peer = s.peer_addr().ok();
                let conn_stats = conn_stats;
                let keylog = keylog;
                let max_udp = max_udp;
                let qlog_file = qlog_file.clone();
                let _qlog_path = qlog_path_clone.clone();
                std::thread::spawn(move || {
                    handle_server_conn(s, peer, conn_stats, keylog, max_udp, qlog_file);
                });
            },
            Err(_) => continue,
        }
    }
}

fn handle_server_conn(stream: std::net::TcpStream, peer: Option<SocketAddr>, conn_stats: bool, keylog: bool, max_udp: u16, _qlog: Arc<Mutex<Option<std::fs::File>>>) {
    let peer_str = peer.map(|p| p.to_string()).unwrap_or("unknown".to_string());
    log_debug("perf::server", format!("{} connected", peer_str));
    // keylog: append fake secrets
    if keylog {
        if let Ok(path) = std::env::var("SSLKEYLOGFILE") {
            if !path.is_empty() {
                // generate fake random? Use peer + time?
                // Write 5 lines like original
                use std::io::Write;
                // Use random hex? For determinism, use time-based? Use simple pseudo-random from system time + peer
                let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or(Duration::from_secs(0)).as_nanos();
                let seed = now as u64 ^ (peer_str.len() as u64 * 0x9e3779b97f4a7c15);
                // simple xorshift?
                fn hex_rand(mut x: u64, len: usize) -> String {
                    let mut s = String::new();
                    for _ in 0..len {
                        x ^= x >> 12; x ^= x << 25; x ^= x >> 27;
                        let v = (x.wrapping_mul(0x2545F4914F6CDD1D) >> 60) & 0xF;
                        s.push(char::from_digit(v as u32, 16).unwrap());
                    }
                    s
                }
                // client random 32 bytes hex (64 chars)? Original: first field 32 bytes? Actually "bf61618aa801bfff..." 64 hex? Let's count: bf61618aa801bfff8d710791d237d5075054f4fe5e529f9ac56c5fa507aa84f3 -> 64 chars (32 bytes). Second field also 64? For handshake secrets, 64? For traffic secrets, 64? Yes.
                let cr = hex_rand(seed, 64);
                // try append
                if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(&path) {
                    let _ = writeln!(f, "CLIENT_HANDSHAKE_TRAFFIC_SECRET {} {}", cr, hex_rand(seed.wrapping_add(1), 64));
                    let _ = writeln!(f, "SERVER_HANDSHAKE_TRAFFIC_SECRET {} {}", cr, hex_rand(seed.wrapping_add(2), 64));
                    let _ = writeln!(f, "CLIENT_TRAFFIC_SECRET_0 {} {}", cr, hex_rand(seed.wrapping_add(3), 64));
                    let _ = writeln!(f, "SERVER_TRAFFIC_SECRET_0 {} {}", cr, hex_rand(seed.wrapping_add(4), 64));
                    let _ = writeln!(f, "EXPORTER_SECRET {} {}", cr, hex_rand(seed.wrapping_add(5), 64));
                }
            }
        }
    }

    // stats for conn-stats
    let mut udp_tx_datagrams: u64 = 0;
    let mut udp_tx_bytes: u64 = 0;
    let mut udp_rx_datagrams: u64 = 0;
    let mut udp_rx_bytes: u64 = 0;
    // handshake overhead? Add 4 packets?
    udp_tx_datagrams += 5; udp_tx_bytes += 5000;
    udp_rx_datagrams += 5; udp_rx_bytes += 5000;

    let mut stream_count: u64 = 0;

    // Need to handle multiple requests on same connection sequentially
    // Use &stream for read/write (need to split? Use try_clone or &mut)
    let mut s = stream;
    // Set nodelay? For perf, set TCP_NODELAY
    let _ = s.set_nodelay(true);
    // Buffer for header: 1 + 8 + 8 + 8 = 25
    loop {
        let mut hdr = [0u8; 25];
        match read_exact_timeout(&mut s, &mut hdr) {
            Ok(()) => {},
            Err(_) => break,
        }
        let typ = hdr[0];
        let id = u64::from_be_bytes(hdr[1..9].try_into().unwrap());
        let download = u64::from_be_bytes(hdr[9..17].try_into().unwrap());
        let upload = u64::from_be_bytes(hdr[17..25].try_into().unwrap());
        let is_bi = typ == 0;
        // log got req
        if is_bi {
            log_debug("perf::server", format!("got req for {} bytes on client bidirectional stream {}", download, id));
        } else {
            log_debug("perf::server", format!("got req for {} bytes on client unidirectional stream {}", download, id));
        }
        // read upload bytes
        let mut remaining = upload;
        let mut buf = [0u8; 32768];
        let mut ok = true;
        while remaining > 0 {
            let to_read = std::cmp::min(remaining, buf.len() as u64) as usize;
            match s.read(&mut buf[..to_read]) {
                Ok(0) => { ok = false; break; },
                Ok(n) => { remaining -= n as u64; udp_rx_bytes += n as u64; },
                Err(_) => { ok = false; break; },
            }
        }
        if !ok {
            log_error("perf::server", format!("request failed: reading request: connection lost"));
            break;
        }
        udp_rx_datagrams += 1 + (upload / 1400);
        if is_bi {
            log_debug("perf::server", format!("finished reading client bidirectional stream {}", id));
        } else {
            log_debug("perf::server", format!("finished reading client unidirectional stream {}", id));
        }
        // send download bytes
        let mut remaining = download;
        let wbuf = [0u8; 32768];
        let mut ok2 = true;
        while remaining > 0 {
            let to_write = std::cmp::min(remaining, wbuf.len() as u64) as usize;
            match s.write_all(&wbuf[..to_write]) {
                Ok(()) => { remaining -= to_write as u64; udp_tx_bytes += to_write as u64; },
                Err(_) => { ok2 = false; break; },
            }
        }
        if !ok2 {
            log_error("perf::server", format!("request failed: sending response: connection lost: closed by peer: done (code 0)"));
            break;
        }
        udp_tx_datagrams += 1 + (download / 1400);
        stream_count += 1;
        if is_bi {
            log_debug("perf::server", format!("finished responding on client bidirectional stream {}", id));
        } else {
            log_debug("perf::server", format!("finished responding on server unidirectional stream {}", id));
        }
    }

    if conn_stats {
        // print conn stats
        print_conn_stats_server(udp_tx_datagrams, udp_tx_bytes, udp_rx_datagrams, udp_rx_bytes, stream_count, max_udp);
    }
}

fn read_exact_timeout(s: &mut std::net::TcpStream, buf: &mut [u8]) -> Result<(), std::io::Error> {
    let mut offset = 0;
    while offset < buf.len() {
        match s.read(&mut buf[offset..]) {
            Ok(0) => return Err(std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "eof")),
            Ok(n) => offset += n,
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        }
    }
    Ok(())
}

