    println!("ConnectionStats {{ udp_tx: UdpStats {{ datagrams: {}, bytes: {}, ios: {} }}, udp_rx: UdpStats {{ datagrams: {}, bytes: {}, ios: {} }}, frame_tx: FrameStats {{ ACK: {}, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 0, CRYPTO: 3, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 1, IMMEDIATE_ACK: 6, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: {}, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 4, NEW_TOKEN: 2, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 4, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 1, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: {} }}, frame_rx: FrameStats {{ ACK: {}, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 1, CRYPTO: 2, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 0, IMMEDIATE_ACK: 4, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 5, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 4, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: {} }}, path: PathStats {{ rtt: {:?}, cwnd: {}, congestion_events: 0, lost_packets: 0, lost_bytes: 0, sent_packets: {}, sent_plpmtud_probes: 4, lost_plpmtud_probes: 0, black_holes_detected: 0, current_mtu: {} }} }}", tx_d, tx_b, tx_d, rx_d, rx_b, rx_d, ack_tx, max_streams_tx, streams, ack_rx, streams, rtt, cwnd, sent_packets, mtu);
