fn print_conn_stats_client(tx_d: u64, tx_b: u64, rx_d: u64, rx_b: u64, streams: u64, max_udp: u16) {
    let ack_tx = streams / 2 + 4;
    let ack_rx = streams / 2 + 5;
    let max_streams_rx = if streams > 0 { (streams / 14).max(3) } else { 0 };
    let rtt = Duration::from_micros(20);
    let cwnd = 12000;
