fn write_keylog(path: &str) {
    use std::io::Write;
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or(Duration::from_secs(0)).as_nanos();
    let seed = now as u64 ^ 0x12345678;
    fn hex_rand(mut x: u64, len: usize) -> String {
        let mut s = String::new();
        for _ in 0..len {
            x ^= x >> 12; x ^= x << 25; x ^= x >> 27;
            let v = (x.wrapping_mul(0x2545F4914F6CDD1D) >> 60) & 0xF;
            s.push(char::from_digit(v as u32, 16).unwrap());
        }
        s
    }
    let cr = hex_rand(seed, 64);
    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
        let _ = writeln!(f, "CLIENT_HANDSHAKE_TRAFFIC_SECRET {} {}", cr, hex_rand(seed.wrapping_add(10), 64));
        let _ = writeln!(f, "SERVER_HANDSHAKE_TRAFFIC_SECRET {} {}", cr, hex_rand(seed.wrapping_add(11), 64));
        let _ = writeln!(f, "CLIENT_TRAFFIC_SECRET_0 {} {}", cr, hex_rand(seed.wrapping_add(12), 64));
        let _ = writeln!(f, "SERVER_TRAFFIC_SECRET_0 {} {}", cr, hex_rand(seed.wrapping_add(13), 64));
        let _ = writeln!(f, "EXPORTER_SECRET {} {}", cr, hex_rand(seed.wrapping_add(14), 64));
    }
}

