fn worker_loop(mut stream: std::net::TcpStream, is_uni: bool, uni_counter: Arc<AtomicU64>, bi_counter: Arc<AtomicU64>, download_size: u64, upload_size: u64, all_stats: Arc<Mutex<Vec<StreamStat>>>, stop: Arc<AtomicBool>, tx_bytes: Arc<AtomicU64>, rx_bytes: Arc<AtomicU64>, total_reqs: Arc<AtomicU64>) {
    let mut wbuf = vec![0u8; 32768];
    let mut rbuf = vec![0u8; 32768];
