            if stop.load(Ordering::SeqCst) {
                // If stop during upload, should we abort? Original would abort and log error. For our fake, finish current? To mimic interrupt, break and log error? But we decided to finish. Let's finish even if stop (to avoid errors). So ignore stop mid-request, continue.
            }
            let to_write = std::cmp::min(remaining, wbuf.len() as u64) as usize;
