            log_debug("perf::client", format!("sending request on client unidirectional stream {}", id));
        } else {
            log_debug("perf::client", format!("sending request on client bidirectional stream {}", id));
        }
        // Send header: type(1) + id(8) + download(8) + upload(8) =25
        let mut hdr = [0u8; 25];
        hdr[0] = if is_uni {1} else {0};
        hdr[1..9].copy_from_slice(&id.to_be_bytes());
        hdr[9..17].copy_from_slice(&download_size.to_be_bytes());
        hdr[17..25].copy_from_slice(&upload_size.to_be_bytes());
        let upload_start = Instant::now();
        if stream.write_all(&hdr).is_err() {
            log_error("perf::client", format!("request failed: connection lost: closed"));
            break;
        }
        // Send upload bytes
        let mut remaining = upload_size;
        let mut ok = true;
        while remaining > 0 {
            if stop.load(Ordering::SeqCst) {
                // If stop during upload, should we abort? Original would abort and log error. For our fake, finish current? To mimic interrupt, break and log error? But we decided to finish. Let's finish even if stop (to avoid errors). So ignore stop mid-request, continue.
            }
            let to_write = std::cmp::min(remaining, wbuf.len() as u64) as usize;
            if stream.write_all(&wbuf[..to_write]).is_err() { ok=false; break; }
            remaining -= to_write as u64;
        }
        if !ok {
            log_error("perf::client", format!("request failed: connection lost: closed"));
            break;
        }
        let upload_end = Instant::now();
        let upload_dur = upload_end.duration_since(upload_start);
        if is_uni {
            log_debug("perf::client", format!("upload finished on client unidirectional stream {}", id));
        } else {
            log_debug("perf::client", format!("upload finished on client bidirectional stream {}", id));
        }
        // Read download bytes, measure FBL (time to first byte)
        let download_start = Instant::now();
        let mut fbl: Option<Duration> = None;
        let mut remaining = download_size;
        let mut ok2 = true;
        while remaining > 0 {
            let to_read = std::cmp::min(remaining, rbuf.len() as u64) as usize;
            match stream.read(&mut rbuf[..to_read]) {
